 static ParameterDescriptor[] Parameters(){var list=new List<ParameterDescriptor>{P("CalibPointGet",ParameterKind.Integer,0,0,1),P("CalibPointInput",ParameterKind.Integer,0,0,1),P("CalibPointTotalNum",ParameterKind.Integer,9,4,16),P("RotPointTotalNum",ParameterKind.Integer,3,0,16),P("TeachEnable",ParameterKind.Boolean,false),P("TeachFlag",ParameterKind.Text,""),P("BasePointX",ParameterKind.Number,0d,-9999999,9999999),P("BasePointY",ParameterKind.Number,0d,-9999999,9999999),P("MoveAlignX",ParameterKind.Number,1d,-99999,99999),P("MoveAlignY",ParameterKind.Number,1d,-99999,99999),P("MoveFirstType",ParameterKind.Integer,1,1,2),P("ChangeDirectionMoveTime",ParameterKind.Integer,3,1,16),P("BaseAngle",ParameterKind.Number,0d,-180,180),P("MoveAngle",ParameterKind.Number,1d,-180,180),P("UseRelativeCoordinates",ParameterKind.Boolean,false),P("CalibOrigin",ParameterKind.Integer,4,0,15),P("RefreshFileEnable",ParameterKind.Boolean,false),P("CalibPathName",ParameterKind.Text,""),P("CameraMode",ParameterKind.Integer,1,1,3),P("HomoFreedom",ParameterKind.Integer,2,1,3),P("WeightFun",ParameterKind.Integer,3,1,3),P("WeightFactor",ParameterKind.Integer,20,1,200),P("DistThreshold",ParameterKind.Integer,30,1,100),P("SampleRatio",ParameterKind.Integer,60,1,100),P("ClearRevision",ParameterKind.Integer,0,0,int.MaxValue),P("ConfigurationUserData",ParameterKind.Text,"{}"),P(ToolDisplayService.SettingsParameter,ParameterKind.Text,""),P("DisplayInputBindings",ParameterKind.Text,"{}"),P(ToolDisplayObjectStore.ParameterName,ParameterKind.Text,"{}")};
